package com.acttub.actingapi.auth;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.stereotype.Service; import com.acttub.actingapi.web.ApiException;
/** Python app.py의 current/optional/rate-limited/consented 네 조합을 이름 그대로 제공한다. */
@Service public class AuthDependencies {private final CurrentUserService current;private final FixedWindowRateLimiter limiter;private final AuthStore store;public AuthDependencies(CurrentUserService current,FixedWindowRateLimiter limiter,AuthStore store){this.current=current;this.limiter=limiter;this.store=store;}public AuthStore.User currentUser(HttpServletRequest request){return current.require(request);}public AuthStore.User optionalUser(HttpServletRequest request){return current.optional(request);}public AuthStore.User rateLimitedUser(HttpServletRequest request){AuthStore.User user=currentUser(request);if(!limiter.allow(user.id().toString(),60))throw new ApiException(429,"rate limit exceeded");return user;}public AuthStore.User consentedUser(HttpServletRequest request){AuthStore.User user=rateLimitedUser(request);if(store.hasPendingConsents(user.id()))throw new ApiException(403,"consent_required");return user;}}
